"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[5697],{5697:a=>{a.exports=JSON.parse('{"meta":{"title":"Agen AI - iMuslim Life","description":"Tanyakan jadwal salat hari ini, arah kiblat, dan tanggal Hijriah kepada Claude, ChatGPT, Gemini, atau Copilot. Hubungkan server MCP gratis kami dalam semenit, tanpa kunci API."},"chip":"Baru: server MCP","h1":"Jadwal salat untuk asisten AI Anda","lede":"Hubungkan Claude, ChatGPT, Gemini, atau Copilot ke server jadwal salat Muslim Companion. Asisten Anda lalu menjawab dengan waktu yang benar-benar dihitung untuk kota dan metode Anda, bukan tebakan.","copy":"Salin","copied":"Tersalin","toolsH2":"Yang bisa dilakukan asisten Anda","toolsSub":"Enam alat hanya-baca. Waktu dihitung menurut zona waktu tempat itu sendiri, dengan metode perhitungan dan mazhab Asar pilihan Anda.","tools":{"prayer":{"title":"Jadwal salat untuk hari apa pun","text":"Subuh, terbit, Zuhur, Asar, Magrib, dan Isya untuk suatu tempat dan tanggal, dalam waktu setempat, beserta tanggal Hijriah."},"next":{"title":"Salat berikutnya","text":"Salat mana yang berikutnya, waktunya, dan berapa menit lagi."},"find":{"title":"Cari tempat","text":"Mengubah kota atau alamat menjadi koordinat dan zona waktu."},"hijri":{"title":"Tanggal Hijriah","text":"Tanggal Islam untuk tanggal Masehi mana pun."},"qibla":{"title":"Arah kiblat","text":"Arah Ka\'bah dari tempat mana pun, dalam derajat dan arah mata angin."},"methods":{"title":"Metode perhitungan","text":"ISNA, Liga Muslim Dunia, Umm al-Qura, Karachi, dan 11 lainnya, serta Asar Hanafi atau standar."}},"setupH2":"Cara menyiapkan","tabDevelopers":"Pengembang","claude":{"s1":"Di <b>claude.ai</b> atau di <b>Claude Desktop</b>, buka <b>Settings \u2192 Connectors</b>.","s2":"Pilih <b>Add custom connector</b>. Beri nama <b>Muslim Companion</b> dan tempel URL server di bawah.","s3":"Simpan. Di sebuah obrolan, aktifkan konektor (dari menu alat) lalu tanyakan: <i>\u201cKapan Magrib di Toronto hari ini?\u201d</i>","note":"Konektor kustom bergantung pada paket Claude Anda. Untuk Claude Code, jalankan perintah di bawah sebagai gantinya."},"chatgpt":{"s1":"Di ChatGPT, buka <b>Settings \u2192 Apps & Connectors</b>, lalu <b>Advanced settings</b>, dan aktifkan <b>Developer mode</b>.","s2":"Pilih <b>Create</b> (konektor baru). Beri nama <b>Muslim Companion</b>, tempel URL server di bawah, dan pilih <b>No authentication</b>.","s3":"Di obrolan baru, tambahkan konektor lalu tanyakan: <i>\u201cBagaimana jadwal salat hari ini di London, dengan Asar Hanafi?\u201d</i>","note":"Konektor mode pengembang bergantung pada paket ChatGPT Anda, dan nama menu bisa berubah antarversi."},"gemini":{"s1":"Buka <b>~/.gemini/settings.json</b> (buat jika belum ada).","s2":"Tambahkan entri <b>muslim-companion</b> di bawah ke dalam <b>mcpServers</b>, lalu mulai ulang Gemini CLI.","s3":"Jalankan <b>/mcp</b> untuk memastikan sudah terhubung, lalu tanyakan jadwal salat."},"vscode":{"s1":"Di proyek Anda, buat <b>.vscode/mcp.json</b> (atau jalankan <b>MCP: Add Server</b> dari Command Palette dan pilih <b>HTTP</b>).","s2":"Tempel konfigurasi di bawah dan klik <b>Start</b> di atas entri server.","s3":"Di Copilot Chat, beralih ke mode <b>Agent</b> dan tanyakan jadwal salat."},"dev":{"s1":"Klien MCP apa pun bisa terhubung: server memakai <b>Streamable HTTP</b>, tanpa status, dan tidak memerlukan kunci API.","s2":"Panggil alat dengan permintaan JSON-RPC <b>POST</b>, seperti contoh di bawah.","s3":"Baca <a>llms.txt</a> untuk ringkasan singkat yang ditulis untuk model bahasa.","note":"Batas: 60 permintaan per menit dan 600 per jam per klien. Simpan jadwal sehari di cache daripada bertanya berulang kali."},"tryAsk":"Coba tanyakan: <i>\u201cKapan Subuh besok di Orlando?\u201d</i> \xb7 <i>\u201cKe mana arah kiblat dari Karachi?\u201d</i> \xb7 <i>\u201cTanggal Hijriah hari ini berapa?\u201d</i> \xb7 <i>\u201cBerapa lama lagi Asar di Toronto, Hanafi?\u201d</i>","privacyH":"Hanya data publik","privacy":"Server ini hanya menyediakan informasi publik: jadwal salat, tanggal Hijriah, arah kiblat, dan metode perhitungan. Tidak perlu akun, dan server tidak dapat melihat atau mengubah apa pun di pengaturan Muslim Companion Anda. Fitur yang bertindak atas nama Anda, seperti membaca jadwal Azan Anda sendiri, akan hadir nanti dan selalu memerlukan Anda masuk serta memberi izin. Lihat <a>Kebijakan Privasi</a> kami.","alexaCta":"Muslim Companion untuk Alexa"}')}}]);